begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,aud,role,created_at) values('a9600000-0000-4000-8000-000000000001','push-initial@example.invalid','authenticated','authenticated',now());
insert into public.mobile_push_tokens(id,user_id,expo_push_token,platform,is_active) values('a9600000-0000-4000-8000-000000000002','a9600000-0000-4000-8000-000000000001','ExponentPushToken[initial-test]','ios',true);
insert into public.mobile_notifications(id,user_id,type,category,title,body) values('a9600000-0000-4000-8000-000000000003','a9600000-0000-4000-8000-000000000001','post_saved','social','Fixture','Local only');
insert into public.mobile_push_deliveries(id,notification_id,user_id,token_id,expo_push_token,platform,send_status,receipt_status,attempt_count) values('a9600000-0000-4000-8000-000000000004','a9600000-0000-4000-8000-000000000003','a9600000-0000-4000-8000-000000000001','a9600000-0000-4000-8000-000000000002','ExponentPushToken[initial-test]','ios','error','error',1);

update public.mobile_push_deliveries set attempt_count=3,initial_attempt_reservation=true,retry_claim_id='a9600000-0000-4000-8000-000000000005' where id='a9600000-0000-4000-8000-000000000004';
select ok(not p.prosecdef and p.proconfig @> array['search_path=""'], 'record_initial_mobile_push_outcomes(jsonb) fixed invoker path') from pg_proc p where p.oid='public.record_initial_mobile_push_outcomes(jsonb)'::regprocedure;
select ok(not has_function_privilege('anon','public.record_initial_mobile_push_outcomes(jsonb)','execute'), 'anon execute boundary for record_initial_mobile_push_outcomes(jsonb)');
select ok(not has_function_privilege('authenticated','public.record_initial_mobile_push_outcomes(jsonb)','execute'), 'authenticated execute boundary for record_initial_mobile_push_outcomes(jsonb)');
select ok(has_function_privilege('service_role','public.record_initial_mobile_push_outcomes(jsonb)','execute'), 'service_role execute boundary for record_initial_mobile_push_outcomes(jsonb)');
select ok(not p.prosecdef and p.proconfig @> array['search_path=""'], 'finish_initial_mobile_push_outcomes(jsonb) fixed invoker path') from pg_proc p where p.oid='public.finish_initial_mobile_push_outcomes(jsonb)'::regprocedure;
select ok(not has_function_privilege('anon','public.finish_initial_mobile_push_outcomes(jsonb)','execute'), 'anon execute boundary for finish_initial_mobile_push_outcomes(jsonb)');
select ok(not has_function_privilege('authenticated','public.finish_initial_mobile_push_outcomes(jsonb)','execute'), 'authenticated execute boundary for finish_initial_mobile_push_outcomes(jsonb)');
select ok(has_function_privilege('service_role','public.finish_initial_mobile_push_outcomes(jsonb)','execute'), 'service_role execute boundary for finish_initial_mobile_push_outcomes(jsonb)');
set local role service_role;
select throws_ok($$select public.record_initial_mobile_push_outcomes(null)$$,'22023',null,'record_initial_mobile_push_outcomes rejects invalid batch');
select throws_ok($$select public.record_initial_mobile_push_outcomes('{}'::jsonb)$$,'22023',null,'record_initial_mobile_push_outcomes rejects invalid batch');
select throws_ok($$select public.record_initial_mobile_push_outcomes('[]'::jsonb)$$,'22023',null,'record_initial_mobile_push_outcomes rejects invalid batch');
select throws_ok($$select public.record_initial_mobile_push_outcomes((select jsonb_agg('{}'::jsonb) from generate_series(1,101)))$$,'22023',null,'record_initial_mobile_push_outcomes rejects invalid batch');
select throws_ok($$select public.finish_initial_mobile_push_outcomes(null)$$,'22023',null,'finish_initial_mobile_push_outcomes rejects invalid batch');
select throws_ok($$select public.finish_initial_mobile_push_outcomes('{}'::jsonb)$$,'22023',null,'finish_initial_mobile_push_outcomes rejects invalid batch');
select throws_ok($$select public.finish_initial_mobile_push_outcomes('[]'::jsonb)$$,'22023',null,'finish_initial_mobile_push_outcomes rejects invalid batch');
select throws_ok($$select public.finish_initial_mobile_push_outcomes((select jsonb_agg('{}'::jsonb) from generate_series(1,101)))$$,'22023',null,'finish_initial_mobile_push_outcomes rejects invalid batch');
select is(public.record_initial_mobile_push_outcomes('[{"delivery_id": "a9600000-0000-4000-8000-000000000004", "claim_id": "a9600000-0000-4000-8000-000000000099", "outcome": {"status": "refused", "error_code": "DeviceNotRegistered", "attempt_count": 1}}]'::jsonb),0,'foreign claim cannot save');
select throws_ok($$select public.record_initial_mobile_push_outcomes('[{"delivery_id": "a9600000-0000-4000-8000-000000000004", "claim_id": "a9600000-0000-4000-8000-000000000005", "outcome": {"status": "refused", "error_code": "DeviceNotRegistered", "attempt_count": 1}}, {"delivery_id": "a9600000-0000-4000-8000-000000000006", "claim_id": "a9600000-0000-4000-8000-000000000005", "outcome": {"status": "refused", "error_code": "DeviceNotRegistered", "attempt_count": 4}}]'::jsonb)$$,'22023',null,'invalid later item rolls back whole save');
select is((select retry_outcome from public.mobile_push_deliveries where id='a9600000-0000-4000-8000-000000000004'),null::jsonb,'first outcome rolled back');
select is(public.record_initial_mobile_push_outcomes('[{"delivery_id": "a9600000-0000-4000-8000-000000000004", "claim_id": "a9600000-0000-4000-8000-000000000005", "outcome": {"status": "refused", "error_code": "DeviceNotRegistered", "attempt_count": 1}}]'::jsonb),1,'save initial outcome');
select is((select attempt_count from public.mobile_push_deliveries where id='a9600000-0000-4000-8000-000000000004'),3,'saving does not refund budget');
select is(public.finish_initial_mobile_push_outcomes('[{"delivery_id": "a9600000-0000-4000-8000-000000000004", "claim_id": "a9600000-0000-4000-8000-000000000099", "outcome": {"status": "refused", "error_code": "DeviceNotRegistered", "attempt_count": 1}}]'::jsonb),0,'foreign claim cannot finalize');
select is((select is_active from public.mobile_push_tokens where id='a9600000-0000-4000-8000-000000000002'),true,'foreign claim cannot retire token');
insert into public.mobile_push_deliveries(id,notification_id,user_id,token_id,expo_push_token,platform,send_status,receipt_status,attempt_count,initial_attempt_reservation,retry_claim_id,retry_outcome)
select 'a9600000-0000-4000-8000-000000000006',notification_id,user_id,token_id,expo_push_token,platform,'error','error',3,true,retry_claim_id,'{"status":"refused","error_code":"DeviceNotRegistered"}'::jsonb from public.mobile_push_deliveries where id='a9600000-0000-4000-8000-000000000004';
select throws_ok($$select public.finish_initial_mobile_push_outcomes('[{"delivery_id":"a9600000-0000-4000-8000-000000000004","claim_id":"a9600000-0000-4000-8000-000000000005"},{"delivery_id":"a9600000-0000-4000-8000-000000000006","claim_id":"a9600000-0000-4000-8000-000000000005"}]')$$,'22023',null,'invalid later finalization rolls back whole batch');
select is((select is_active from public.mobile_push_tokens where id='a9600000-0000-4000-8000-000000000002'),true,'batch rollback restores retired token');
select is((select attempt_count from public.mobile_push_deliveries where id='a9600000-0000-4000-8000-000000000004'),3,'batch rollback restores full reservation');
select ok((select retry_outcome is not null from public.mobile_push_deliveries where id='a9600000-0000-4000-8000-000000000004'),'batch rollback retains saved outcome');
delete from public.mobile_push_deliveries where id='a9600000-0000-4000-8000-000000000006';
select is(public.finish_initial_mobile_push_outcomes('[{"delivery_id": "a9600000-0000-4000-8000-000000000004", "claim_id": "a9600000-0000-4000-8000-000000000005", "outcome": {"status": "refused", "error_code": "DeviceNotRegistered", "attempt_count": 1}}]'::jsonb),1,'finish initial refusal');
select is((select attempt_count from public.mobile_push_deliveries where id='a9600000-0000-4000-8000-000000000004'),1,'known outcome refunds unused budget');
select is((select initial_attempt_reservation from public.mobile_push_deliveries where id='a9600000-0000-4000-8000-000000000004'),false,'reservation cleared');
select is((select is_active from public.mobile_push_tokens where id='a9600000-0000-4000-8000-000000000002'),false,'token retired atomically');
select is(public.finish_initial_mobile_push_outcomes('[{"delivery_id": "a9600000-0000-4000-8000-000000000004", "claim_id": "a9600000-0000-4000-8000-000000000005", "outcome": {"status": "refused", "error_code": "DeviceNotRegistered", "attempt_count": 1}}]'::jsonb),0,'repeated completion inert');
reset role;
select * from finish();
rollback;
